function getTZforStop(stop_id)
{
  let n = "";
  let rt = getRecordForStop(stop_id)
  if(rt.length > 0)
  {
    n = rt[6];
  }
  return(n);
}


function getStopFromID(stop_id)
{
  let s = null;
  let r = getRecordForStop(stop_id);
  if(r.length == 12)
  {
    s = new Object();
    s.stop_id = r[0];
    s.stop_name = r[1];
    s.stop_desc = r[2];
    s.platform_name = r[3];
    s.lat = r[4];
    s.lon = r[5];
    s.timezone = r[6];
    s.level_id = r[7];
    s.parent = r[8];
    s.wchair = r[9];
    s.facilities = r[10];
    s.routes = r[11];
    s.routeArray = [];
    if(r[11] != "") s.routeArray = r[11].split(",");
  }
  else report("60 no record for stop_id " + stop_id);
  return(s);
}

