function stopidIsInArray(stopid, array)
{
  let k = array.length;
  let i = 0;
  let b = false;
  while(!b && (i < k))
  {
    if(array[i] == stopid) b = true;
    else i+= 12;
  }
  return(b);
}

function isInArray(d, array)
{
  let k = array.length;
  let i = 0;
  let b = false;
  while(!b && (i < k))
  {
    if(array[i] == d) b = true;
    else i+= 1;
  }
  return(b);
}

