// returns empty array if no record found
function getRecordsForParent(stop_id)
{
  let ii = 0;
  let kk = stop_Categories.length;
  let b = true;
  let r = [];
  let a = [];
  let pi = "";
  if(typeof stop_id !== 'undefined')
  {
  if(stop_id.indexOf("place-") != -1) pi = stop_id;
  else pi = getParentIdFromId(stop_id);
//  report("198 pi = " + pi);
  let j = pi.indexOf(",");
  if(j != -1) pi = substring(0, j);   
  if((pi == "") || (pi == " "))
  {
//    report("481");
    r.push(getRecordForStop(stop_id));  
  }
  else
  {
//    report("486");
    while(ii < kk)
    {
      a = stop_Categories[ii];
      let k = a.length;
      let i = 0;
      while(i < k)
      {
//        if((a[i] == pi) || (a[i+8].indexOf(pi) != -1))
        if(isParentOfRecord(a, i, pi))
        {
          let rr = [];
          for(j = 0; j < 12; j++)
          {
            rr.push(a[i + j]);   
          }
          r.push(rr);
        }
      i += 12;
      }
      ii += 1;
    }
  }
  }
  return(r);
}

function isParentOfRecord(record, i, pi)
{
  let b = false;
  if(record[i] == pi) b = true;
  else
  {
    let x = record[i+8];
    if(typeof x !== 'undefined') 
    {
//        report("451 x undefined for " + record[i]);
        let a = x.split(",");
        let k = a.length;
        let j = 0;
        while(!b && (j < k))
        {
            if(pi == a[j]) b = true;
            j += 1;
        }
    }
  }
  return(b);
}

function getDescriptionForStop(stop_id)
{
  let r = getRecordForStop(stop_id);
  let d = "";
  if(r.length > 0)
  {
    d = r[STOP_DESC]; 
    if(stop_id.indexOf("place") != -1) d = r[STOP_NAME];
    else if((d == "") || (d == " "))
    {
      if(r[PLATFORM_NAME].length > 2) d = r[STOP_NAME] + " " + r[PLATFORM_NAME];
      else d = d = r[STOP_NAME];
    }
  }
  else 
  {
      d = getStopNameFromID(stop_id);
      report("496 getDescriptionForStop " + stop_id + " r.length = " + r.length);
  }
  return(d);
}

function getStopNameFromID(stop_id1)
{
  let stop_id = stop_id1;
  let d = "";
//  if(stop_id.indexOf("T_") != -1) stop_id = stop_id.substring(2);
  if((typeof stop_id !== 'undefined') && (stop_id != ""))
  {
  let r = getRecordForStop(stop_id);
  if((r.length == 0) && (stop_id.indexOf("place-") == 0))
  {
    r = getRecordForStopByParent(stop_id);
  }
  if(r.length > 0)
  {
    d = r[STOP_NAME]; 
    if(d == "")
    {
      d = r[STOP_DESC];
    }
    TZPlace2 = r[6];
  }
//  report("498 " + stop_id + " " + d);
  if(d == "Middleborough/Lakeville") d = "Middleborough/ Lakeville";
//  report("644 getStopNameFromID " + stop_id1  + " " + d);
  }
  return(d);
}

function getStopIdFromName(stop_name)
{
  let r = getRecordForStopByName(stop_name);
  let d = "";
  if(r.length > 0)
  {
    d = r[STOP_ID]; 
  }
  else
  {
     r = getRecordForStop(stop_name);
     if(r.length > 0)
     {
       d = r[STOP_ID]; 
     }
     else report("no record for stop " + stop_name);
  }
//  if(stop_name == "Middleborough / Lakeville") d = "Middleborough/Lakeville";
  return(d);
}

