function getStopIdForNumber(number, line)
{
  let n = number;
  if(line == "MN")
  {
   n = "MNR_" + number;
   switch(Number(number))
   {
    case 1: n = "NewYork-Grand-Central-NY"; break;
    case 33: n = "Croton-Harmon-NY"; break;
    case 108: n = "NewRochelle-NY"; break;
    case 51: n = "Poughkeepsie-NY"; break;
    case 134: n = "Westport-NY"; break;
    case 18: n = "Yonkers-NY"; break;
    case 140: n = "Bridgeport-CT"; break;
    case 116: n = "Greenwich-CT"; break;
    case 145: n = "Milford-CT"; break;
    case 151: n = "NewHaven_StateSt-CT"; break;
    case 149: n = "NewHaven-CT"; break;
    case 131: n = "SouthNorwalk-CT"; break;
    case 124: n = "Stamford-CT"; break;
    case 143: n = "Stratford-CT"; break;
    case 190: n = "WestHaven-CT"; break;
    default: break;
   }
  }
  else if(line.indexOf("LI") == 0)
  {
    n = "LI" + number;
  }
  else if(line.indexOf("B_") == 0)
  {
    n = "B_" + number;
  }
  else if(line.indexOf("AMS") == 0)
  {
    n = "AMS" + number;   
  }
  else if(line.indexOf("VIA") == 0)
  {
    n = "VIA" + number;   
  }
  else if(line.indexOf("NY") == 0)
  {
    n = "NYT" + number;   
  }
  return(n);
}


