function addStopGroupToCategories(a, carriername)
{
//  report("240 addStopGroup for " + carriername + " " + a.length);
  stop_Categories.push(a);
  let k = StopListData.length;
  let i = 0;
  let b = true;
  while(b && (i < k))
  {
    if(carriername == StopListData[i + 2])
    {
      b = false;
      if(StopListData[i + 1] == null)
      {
        StopListData[i + 1] =  stop_Categories[ stop_Categories.length -1]; 
      }
    }
    i += 3;
  }
}

